using System;
using Alis.Reactive.PlanModel;

namespace Alis.Reactive
{
    /// <summary>
    /// Immutable registration of a component in the reactive plan.
    /// Populated at view render time by each vertical slice's HtmlExtensions.
    /// Consumed by plan authoring when it shapes bindings, gather payloads, and validation metadata.
    /// </summary>
    internal sealed class ComponentRegistration
    {
        /// <summary>DOM element ID generated by IdGenerator from the model expression.</summary>
        public string ComponentId { get; }

        /// <summary>Model property path (e.g., "AdmissionDate", "Address.Street") — key in RegisteredComponents.</summary>
        public string BindingPath { get; }

        /// <summary>Component slice metadata declared once on the component type.</summary>
        internal ComponentMetadata Component { get; }

        /// <summary>Canonical browser member used when this component contributes a bound value.</summary>
        internal CapabilityProperty Binding { get; }

        /// <summary>
        /// Canonical shape of the bound member. This is authored once when the component is
        /// rendered and reused anywhere the framework needs to read or compare that value.
        /// </summary>
        internal ValueShape BindingShape { get; }

        /// <summary>
        /// NEVER make public. Constructed exclusively by framework builders. Public constructors
        /// on framework-owned contract types allow devs to bypass the builder API and create invalid plan state.
        /// </summary>
        internal ComponentRegistration(
            string componentId,
            ComponentMetadata component,
            string bindingPath,
            ValueShape bindingShape)
        {
            ComponentId = componentId;
            Component = component;
            BindingPath = bindingPath;
            Binding = component.Binding
                ?? throw new InvalidOperationException("Bindable component registration requires a declared binding path.");
            BindingShape = bindingShape;
        }
    }
}
